CREATE TABLE users (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE documents (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, file_name VARCHAR(255) NOT NULL, stored_path VARCHAR(512) NOT NULL, file_type VARCHAR(20) NOT NULL, file_size BIGINT NOT NULL, status VARCHAR(20) NOT NULL, failure_reason TEXT, uploaded_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, analyzed_at TIMESTAMP);
CREATE TABLE analysis_results (id UUID PRIMARY KEY, document_id UUID UNIQUE NOT NULL REFERENCES documents(id) ON DELETE CASCADE, summary TEXT NOT NULL, overall_risk_score INT NOT NULL, overall_risk_level VARCHAR(10) NOT NULL, key_entities TEXT NOT NULL, clause_count INT NOT NULL, high_risk_count INT NOT NULL, medium_risk_count INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE clauses (id UUID PRIMARY KEY, document_id UUID NOT NULL REFERENCES documents(id) ON DELETE CASCADE, clause_index INT NOT NULL, clause_text TEXT NOT NULL, category VARCHAR(40) NOT NULL, risk_level VARCHAR(10) NOT NULL, risk_score INT NOT NULL, risk_reason TEXT, matched_rule_id UUID);
CREATE TABLE risk_rules (id UUID PRIMARY KEY, name VARCHAR(150) NOT NULL, category VARCHAR(40) NOT NULL, pattern TEXT NOT NULL, risk_level VARCHAR(10) NOT NULL, weight INT NOT NULL, explanation TEXT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE audit_logs (id UUID PRIMARY KEY, user_id UUID REFERENCES users(id) ON DELETE SET NULL, action VARCHAR(60) NOT NULL, entity_type VARCHAR(60) NOT NULL, entity_id VARCHAR(80), timestamp TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, ip_address VARCHAR(64));
CREATE INDEX idx_documents_user ON documents(user_id); CREATE INDEX idx_documents_status ON documents(status); CREATE INDEX idx_clauses_document ON clauses(document_id); CREATE INDEX idx_audit_user ON audit_logs(user_id);
